DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.admin_save_directory(uuid,jsonb)'::regprocedure) INTO f; f:=replace(f,'p_id IS NULL','(p_id IS NULL OR p_id=''00000000-0000-0000-0000-000000000000''::uuid)'); EXECUTE f; SELECT pg_get_functiondef('public.admin_save_rotation(uuid,uuid,timestamptz,timestamptz,text,text,text)'::regprocedure) INTO f; f:=replace(f,'p_id IS NULL','(p_id IS NULL OR p_id=''00000000-0000-0000-0000-000000000000''::uuid)'); EXECUTE f; END $$;
CREATE OR REPLACE FUNCTION public.nearest_pharmacies_filtered(p_lat double precision,p_lng double precision,p_search text DEFAULT NULL,p_max_km double precision DEFAULT NULL,p_on_duty boolean DEFAULT false,p_with_phone boolean DEFAULT false,p_limit integer DEFAULT 50,p_region text DEFAULT NULL,p_department text DEFAULT NULL,p_city text DEFAULT NULL) RETURNS TABLE(id uuid,name text,address text,locality text,city text,phone text,opening_hours text,lat double precision,lng double precision,on_duty boolean,on_duty_until timestamptz,distance_km double precision) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM public.search_pharmacy_directory(p_lat,p_lng,p_search,p_max_km,p_on_duty,p_with_phone,p_limit,p_region,p_department,p_city) $$;
CREATE OR REPLACE FUNCTION public.nearest_pharmacies(p_lat double precision,p_lng double precision,p_search text DEFAULT NULL,p_max_km double precision DEFAULT NULL,p_on_duty boolean DEFAULT false,p_with_phone boolean DEFAULT false,p_limit integer DEFAULT 50) RETURNS TABLE(id uuid,name text,address text,locality text,city text,phone text,opening_hours text,lat double precision,lng double precision,on_duty boolean,on_duty_until timestamptz,distance_km double precision) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT * FROM public.search_pharmacy_directory(p_lat,p_lng,p_search,p_max_km,p_on_duty,p_with_phone,p_limit) $$;
CREATE OR REPLACE FUNCTION public.pharmacies_with_medicine(p_medicine_id uuid,p_lat double precision,p_lng double precision,p_limit integer DEFAULT 30) RETURNS TABLE(id uuid,name text,address text,locality text,city text,phone text,lat double precision,lng double precision,on_duty boolean,quantity integer,price_fcfa integer,stock_updated_at timestamptz,distance_km double precision) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT p.id,p.name,p.address,p.locality,p.city,p.phone,p.lat,p.lng,(r.id IS NOT NULL),s.quantity,s.price_fcfa,s.updated_at,public.distance_km(p_lat,p_lng,p.lat,p.lng) FROM public.pharmacy_stock s JOIN public.pharmacies p ON p.id=s.pharmacy_id LEFT JOIN LATERAL public.pharmacy_duty_at(p.id) r ON true WHERE s.medicine_id=p_medicine_id AND s.quantity>0 ORDER BY public.distance_km(p_lat,p_lng,p.lat,p.lng),p.id LIMIT LEAST(GREATEST(p_limit,1),100) $$;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.demo_pharmacies_with_medicine(uuid,double precision,double precision)'::regprocedure) INTO f; f:=replace(f,'p.opening_hours','p.habitual_hours'); f:=replace(f,'(p.is_on_duty AND p.duty_starts_at <= now() AND p.on_duty_until > now())','EXISTS(SELECT 1 FROM public.pharmacy_duty_at(p.id))'); EXECUTE f; END $$;